"""Build Redox model instances from raw JSON payloads.

Vendored from ``gen_redox_lib`` and copied into the ``redox`` package on every
regeneration - edit it there, not here.
"""

import contextlib
from importlib import import_module
from json import loads
from typing import TypeAlias
from warnings import warn

from . import generic
from .abstract_base import EventTypeAbstractModel, GenericEventTypeAbstractModel, lenient_ingest

JSONValue: TypeAlias = bool | int | float | str | None
JSONType: TypeAlias = list["JSONType"] | dict[str, "JSONValue | JSONType"]
JsonPayload: TypeAlias = str | JSONType


def get_model_and_event(redox_dict: dict) -> tuple[str, str]:
    meta = redox_dict.get("Meta")
    if not meta:
        msg = "Unable to find Meta attribute of JSON payload."
        raise ValueError(msg)

    model = meta["DataModel"].replace(" ", "")  # PatientAdmin, Scheduling, ...
    event = meta["EventType"]  # NewPatient, Reschedule, ...

    # The SSO data model uses hyphenated event names.
    if "-" in event:
        event = event.replace("-", " ").title().replace(" ", "")

    return model, event


def get_class_type(redox_dict: dict) -> type[EventTypeAbstractModel]:
    data_model, event_type = get_model_and_event(redox_dict)

    model_module = None
    with contextlib.suppress(ModuleNotFoundError):
        model_module = import_module(f"redox.{data_model.lower()}")
    if model_module is None:
        msg = f"Couldn't find Redox model module for {data_model}"
        raise AttributeError(msg)

    event_class = getattr(model_module, event_type, None)
    if event_class is None:
        msg = f"Couldn't find Redox event class for {event_type}"
        raise AttributeError(msg)
    return event_class


def redox_object_factory(
    json_payload: JsonPayload,
    *,
    lenient: bool = False,
) -> EventTypeAbstractModel | list[EventTypeAbstractModel] | None:
    """Return the Redox model instance(s) for ``json_payload``.

    The concrete type is chosen from the payload's ``Meta.DataModel`` /
    ``Meta.EventType``. Accepts a JSON string or an already-parsed dict/list.
    Set ``lenient=True`` to drop unknown fields instead of raising.
    """
    if lenient:
        with lenient_ingest():
            return redox_object_factory(json_payload)

    if json_payload is None:
        return None
    if isinstance(json_payload, str):
        json_payload = loads(json_payload)
    if isinstance(json_payload, list):
        return [_one(item) for item in json_payload]
    return _one(json_payload)


def _one(payload: object) -> EventTypeAbstractModel:
    if isinstance(payload, str):
        payload = loads(payload)
    if not isinstance(payload, dict):
        msg = f"Can only create Redox objects from a valid JSON payload, got {type(payload)}"
        raise TypeError(msg)
    return get_class_type(payload).model_validate(payload)


def from_redox_to_generic(
    redox_instance: EventTypeAbstractModel,
) -> GenericEventTypeAbstractModel | None:
    """Convert a "proper Redox" event model to its composable generic form."""
    if not isinstance(redox_instance, EventTypeAbstractModel):
        msg = "from_redox_to_generic only converts event-type objects; use the cast_from classmethod for other data."
        raise TypeError(msg)

    redox_dict = redox_instance.model_dump()
    data_model = redox_dict["Meta"]["DataModel"]
    event_type = redox_dict["Meta"]["EventType"]

    model_module = getattr(generic, data_model, None)
    if model_module is None:
        warn(f"Couldn't find the generic Redox model module for {data_model}", stacklevel=2)
        return None

    event_class = getattr(model_module, event_type, None)
    if event_class is None:
        warn(f"Couldn't find the generic Redox event class for {event_type}", stacklevel=2)
        return None

    return event_class(**redox_dict)
